  const d = new Date('2020-08-07T12:00-07:00')
  expect(dayjs.tz(d, 'America/Vancouver').format()).toBe('2020-08-07T12:00:00-07:00')
  expect(dayjs.tz(d, 'America/Vancouver').valueOf()).toBe(d.getTime())
})

it('tz with timestamp input', () => {
  const d = new Date('2020-08-07T12:00-07:00')
  expect(dayjs.tz(d.getTime(), 'America/Vancouver').format()).toBe('2020-08-07T12:00:00-07:00')
})

it('tz with Dayjs input', () => {
  const d = new Date('2020-08-07T12:00-07:00')
  expect(dayjs.tz(dayjs(d), 'America/Vancouver').format()).toBe('2020-08-07T12:00:00-07:00')
})

it('tz with Date input in other zones', () => {
  const d = new Date('2020-08-07T12:00-07:00')
